import type { ComponentProps, ReactNode } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Stepper.module.css'

export interface StepperStep {
  label: ReactNode
  description?: ReactNode
  /** Override the status worked out from `current`, e.g. to flag a step with an error. */
  status?: 'complete' | 'current' | 'upcoming' | 'error'
}

export interface StepperProps extends Omit<ComponentProps<'nav'>, 'children'> {
  steps: StepperStep[]
  /** 0-based index of the step the reader is on. Steps before it are complete. */
  current: number
  orientation?: 'horizontal' | 'vertical'
  size?: 'sm' | 'md'
  /**
   * Makes finished steps (and the current one) buttons that go back to
   * them. Upcoming steps stay plain: they cannot be skipped to.
   */
  onStepClick?: (index: number) => void
  /** The nav landmark's name. */
  'aria-label'?: string
}

const statusText = { complete: 'completed', current: 'current', upcoming: 'not started', error: 'has an error' }

export function Stepper({
  steps,
  current,
  orientation = 'horizontal',
  size = 'md',
  onStepClick,
  'aria-label': ariaLabel = 'Progress',
  className,
  ...props
}: StepperProps) {
  return (
    <nav aria-label={ariaLabel} className={cn(styles.stepper, styles[orientation], styles[size], className)} {...props}>
      <ol className={styles.list}>
        {steps.map((step, i) => {
          const status = step.status ?? (i < current ? 'complete' : i === current ? 'current' : 'upcoming')
          const clickable = onStepClick !== undefined && status !== 'upcoming'
          const marker = (
            <span className={styles.marker} aria-hidden="true">
              {status === 'complete' ? <Icon name="check" /> : status === 'error' ? <Icon name="danger" /> : i + 1}
            </span>
          )
          const text = (
            <span className={styles.text}>
              <span className={styles.label}>
                {step.label}
                {/* Said, not shown: the marker carries it visually. */}
                <span className={styles.srOnly}>, {statusText[status]}</span>
              </span>
              {step.description && <span className={styles.description}>{step.description}</span>}
            </span>
          )
          return (
            <li
              key={i}
              className={cn(styles.step, styles[status])}
              aria-current={status === 'current' ? 'step' : undefined}
            >
              {clickable ? (
                <button type="button" className={styles.target} onClick={() => onStepClick(i)}>
                  {marker}
                  {text}
                </button>
              ) : (
                <span className={styles.target}>
                  {marker}
                  {text}
                </span>
              )}
              {i < steps.length - 1 && <span className={styles.connector} aria-hidden="true" />}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

.stepper {
  --step-marker: var(--space-8);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--foreground);
}

.sm {
  --step-marker: var(--space-6);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
}

.list {
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
}
.vertical .list {
  flex-direction: column;
}

.step {
  position: relative;
  display: flex;
  flex: 1;
  min-inline-size: 0;
}

.target {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
}
button.target {
  cursor: var(--cursor-button);
}
button.target:hover .label {
  text-decoration: underline;
  text-underline-offset: 0.2em;
}
button.target:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.marker {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  inline-size: var(--step-marker);
  block-size: var(--step-marker);
  border: 2px solid var(--control-border);
  border-radius: 9999px;
  background: var(--background);
  color: var(--muted-foreground);
  font-size: var(--text-body-sm);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.marker :global(svg) {
  inline-size: 60%;
  block-size: 60%;
}

/* Complete and current share the primary colour; the filled disc says
   done, the ring says here. */
.complete .marker {
  border-color: var(--primary);
  background: var(--primary);
  color: var(--primary-foreground);
}
.current .marker {
  border-color: var(--primary-text);
  color: var(--primary-text);
}
.error .marker {
  border-color: var(--danger-text);
  background: var(--danger-subtle);
  color: var(--danger-text);
}

.text {
  display: flex;
  flex-direction: column;
  min-inline-size: 0;
  /* Line the first line of the label up with the middle of the marker. */
  padding-block-start: calc((var(--step-marker) - 1lh) / 2);
}

.label {
  font-weight: 500;
}
.upcoming .label {
  color: var(--muted-foreground);
}
.error .label {
  color: var(--danger-text);
}

.description {
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--muted-foreground);
}

/* The line to the next step: --border ahead, --primary once this step is
   done. Horizontal, it runs from this marker to the next along the
   markers' centre line, with the text below, so every step gets the same
   width whatever its label. Vertical, it runs down beside the text. */
.connector {
  border-radius: 9999px;
  background: var(--border);
}
.complete .connector {
  background: var(--primary);
}

.horizontal .step {
  flex-direction: column;
}
.horizontal .target {
  flex-direction: column;
  gap: var(--space-2);
  padding-inline-end: var(--space-3);
}
.horizontal .text {
  padding-block-start: 0;
}
.horizontal .connector {
  position: absolute;
  inset-block-start: calc(var(--step-marker) / 2 - 1px);
  inset-inline: calc(var(--step-marker) + var(--space-2)) var(--space-2);
  block-size: 2px;
}

.vertical .step {
  flex-direction: column;
}
.vertical .connector {
  inline-size: 2px;
  min-block-size: var(--space-6);
  margin: var(--space-1) 0 var(--space-1) calc(var(--step-marker) / 2 - 1px);
}

.srOnly {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (pointer: coarse) {
  button.target {
    min-block-size: 44px;
  }
}
